/* Shared fraud operations workflow. All decisions and model evidence remain server-owned. */
(() => {
  const root=document.querySelector('#operations-workspace'), esc=escapeHtml;
  let loading=false;
  const amount=items=>formatSar(items.reduce((sum,item)=>sum+Number(item||0),0));
  async function loadOperations(){
    if(loading)return;loading=true;
    try{
      const [saved,registry,proposals,llm]=await Promise.all([backendJSON('/assessments'),backendJSON('/journey-models'),backendJSON('/scenario-proposals'),backendJSON('/llm/status')]);
      const latest=new Map();for(const r of saved)if(r.caseData?.modelAssessment&&!latest.has(r.caseId))latest.set(r.caseId,r);
      const rows=[...latest.values()], data=rows.map(r=>r.caseData);
      const cards=[['Saved cases',rows.length,'Actual saved synthetic assessments'],['Cases in progress',data.filter(c=>['Triage','Investigation','Decision pending'].includes(c.workflow?.stage)).length,'Named case owners and audit history'],['Resolved outcomes',data.filter(c=>c.outcome&&!/Suspected|Inconclusive/.test(c.outcome)).length,'Recorded specialist classifications'],['Confirmed violations',data.filter(c=>c.outcome==='Confirmed violation').length,'Recorded outcomes; no notices issued'],['Recorded prevented amount',amount(data.filter(c=>['Prevented before payment','Partially prevented'].includes(c.financialOutcome)).map(c=>c.preventedAmount)),'Synthetic values; no live payment intervention'],['Governance reviews',proposals.proposals.filter(p=>!['Active','Rejected'].includes(p.status)).length,'Examples awaiting a review stage']];
      root.innerHTML=`<div class="ops-hero"><p class="eyebrow">MADAR · ENTERPRISE FRAUD OPERATIONS</p><h2>One place to investigate.<br>A clear path to a decision.</h2><p>Bring findings from existing fraud capabilities into a shared case process: explain the evidence, assign ownership, record decisions and track governance.</p><div class="ops-actions"><button class="primary-btn" data-ops-view="connected">Open connected case example</button><button class="secondary-btn" data-ops-view="intake">Import synthetic findings</button></div><small>Working prototype · synthetic data · no live enterprise connections</small></div>
        <div class="ops-process" aria-label="Case process"><span>1 Receive findings</span><span>2 Explain & triage</span><span>3 Investigate</span><span>4 Record outcome</span><span>5 Review & improve</span></div>
        <div class="ops-metrics">${cards.map(([label,value,detail])=>`<article><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(detail)}</small></article>`).join('')}</div>
        <section class="panel"><div class="ops-section-heading"><div><p class="eyebrow">SHARED CASE WORK</p><h3>Shared case register</h3></div><button class="secondary-btn" data-ops-view="queue">Open investigation queue</button></div><p>Each case retains the originating detector, evidence, specialist decisions and workflow history.</p><div class="cj-table-wrap"><table class="ops-table"><thead><tr><th>Case / capability</th><th>Evidence</th><th>Workflow</th><th>Owner</th><th>Next step</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.caseData.scenario)}</strong><small>${esc(r.caseId)} · ${esc(r.assessmentSource==='cross-journey'?'Connected journeys':r.journey)}</small></td><td>${esc(r.complete?'Assessed':'Incomplete')}</td><td>${esc(r.caseData.workflow?.stage||'New')}</td><td>${esc(r.caseData.workflow?.assignedTo||'Unassigned')}</td><td><button class="secondary-btn" data-ops-case="${esc(r.caseId)}">Review case</button></td></tr>`).join('')||'<tr><td colspan="5">No saved model cases yet. Open the connected example or import synthetic evidence.</td></tr>'}</tbody></table></div></section>
        <div class="ops-columns"><section class="panel"><p class="eyebrow">CAPABILITY INPUTS</p><h3>Existing detection feeds the process</h3><p>These bundled models demonstrate input from several capabilities. Connections to your existing enterprise use cases are the next integration step.</p><ul>${registry.models.map(m=>`<li><strong>${esc(m.journey)}</strong> · ${esc(m.algorithm)} <small>Bundled synthetic model</small></li>`).join('')}</ul><button class="text-btn" data-ops-view="method">Inspect capability registry →</button></section><section class="panel"><p class="eyebrow">SPECIALIST ASSISTANCE</p><h3>Explain the evidence with an LLM</h3><p>Prepare a plain-language case brief, cited findings, missing-evidence questions and suggested investigation checks.</p><span class="status-chip">${llm.configured?'API configured · on-demand':'API not configured'}</span><p>LLM drafts require specialist verification. They do not set risk, issue violations or change payment status.</p><p><strong>Value to measure:</strong> time to first review, investigation duration, useful findings, confirmed outcomes and verified intervention amounts. No time-saving or detection uplift has been measured yet.</p></section></div>`;
      root.querySelectorAll('[data-ops-view]').forEach(button=>button.onclick=()=>{useAssessedPortfolio();renderAll();switchView(button.dataset.opsView)});
      root.querySelectorAll('[data-ops-case]').forEach(button=>button.onclick=()=>{const r=latest.get(button.dataset.opsCase);const index=cases.findIndex(c=>c.id===r.caseId);if(index<0)cases.push(r.caseData);else cases[index]=r.caseData;useAssessedPortfolio();selectedId=r.caseId;activeFilter='All';activeJourney='All';activeRegion='All';searchQuery='';document.querySelector('#case-search').value='';renderAll();switchView('queue')});
    }catch(error){root.innerHTML=`<div class="empty-state"><h2>Fraud Operations is unavailable</h2><p>${esc(error.message)}</p><button id="ops-retry" class="primary-btn">Retry connection</button></div>`;root.querySelector('#ops-retry').onclick=loadOperations}
    finally{loading=false}
  }
  function renderAssistant(draft,host){
    const renderItem=item=>`<p>${esc(item.text)} <small>[${item.evidenceIds.map(esc).join(', ')}]</small></p>`;
    host.innerHTML=`<span class="status-chip">Unreviewed LLM draft</span><p>${esc(draft.provider)} · ${esc(draft.model)} · ${esc(new Date(draft.generatedAt).toLocaleString())}</p>${renderItem(draft.explanation.overview)}${[['Findings','findings'],['Questions to investigate','questions'],['Suggested checks','nextSteps']].map(([name,key])=>`<h4>${name}</h4>${draft.explanation[key].map(renderItem).join('')||'<p>None supplied.</p>'}`).join('')}<details><summary>Inspect cited evidence</summary>${draft.facts.map(f=>`<div id="fact-${esc(f.id)}"><strong>${esc(f.id)}</strong><pre>${esc(JSON.stringify(f.value,null,2))}</pre></div>`).join('')}</details><p class="session-note">Evidence IDs are checked against this assessment. Citations do not guarantee factual accuracy; verify the draft against the evidence before using it in a decision.</p>`;
  }
  function enhanceCase(){
    const item=portfolioCases().find(c=>c.id===selectedId), panel=document.querySelector('#case-panel');
    if(!item?.assessmentId || !item.modelAssessment)return;
    const workflow=item.workflow||{stage:'New',assignedTo:'',revision:0};
    const section=document.createElement('section');section.className='detail-section ops-case-work';
    section.innerHTML=`<p class="eyebrow">CASE OWNERSHIP & PROCESS</p><h3>Manage this investigation</h3><p>Move through adjacent stages. Closing requires a resolved specialist outcome. This is a prototype workflow with named reviewers, not authenticated enterprise roles.</p><form id="ops-workflow-form"><div class="form-grid"><label>Case owner<input name="owner" required maxlength="120" value="${esc(workflow.assignedTo)}" placeholder="Assign a specialist"></label><label>Stage<select name="stage">${['New','Triage','Investigation','Decision pending','Closed'].map(stage=>`<option ${workflow.stage===stage?'selected':''}>${stage}</option>`).join('')}</select></label><label>Reviewer name<input name="reviewer" required maxlength="120" placeholder="Your name"></label><label>Work note<textarea name="note" required maxlength="2000" rows="2" placeholder="Evidence reviewed or next action"></textarea></label></div><button class="primary-btn" type="submit">Save workflow update</button><p role="status" class="ops-workflow-status"></p></form>`;
    panel.prepend(section);
    const form=section.querySelector('form');form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const saved=await backendJSON('/case-workflow',{caseId:item.id,assessmentId:item.assessmentId,assignedTo:form.elements.owner.value.trim(),workflowStage:form.elements.stage.value,expectedRevision:workflow.revision,actorName:form.elements.reviewer.value.trim(),note:form.elements.note.value.trim()});Object.assign(item,saved.caseData);renderAll();showToast('Case ownership and workflow saved')}catch(error){form.querySelector('.ops-workflow-status').textContent=error.message;button.disabled=false}};
    const assistant=document.createElement('section');assistant.className='detail-section ops-assistant';assistant.innerHTML='<p class="eyebrow">LLM CASE EXPLANATION</p><h3>Prepare a case brief</h3><p>Explain saved evidence, identify questions and suggest investigation checks. Model scores and specialist decisions remain unchanged.</p><button class="primary-btn" disabled>Checking API setup…</button><p class="ops-llm-status" role="status"></p><div class="ops-llm-draft"></div>';
    const overview=panel.querySelector('.ai-summary-section');if(overview)overview.after(assistant);else panel.append(assistant);
    const button=assistant.querySelector('button'), status=assistant.querySelector('.ops-llm-status'), draftHost=assistant.querySelector('.ops-llm-draft');
    const attached=()=>assistant.isConnected && item.assessmentId===cases.find(c=>c.id===item.id)?.assessmentId;
    Promise.all([backendJSON('/llm/status'),backendJSON('/case-explanation',{caseId:item.id,assessmentId:item.assessmentId,generate:false})]).then(([config,response])=>{if(!attached())return;button.textContent=response.draft?'Explanation saved':config.configured?'Generate LLM explanation':'API setup required';button.disabled=!config.configured||!!response.draft;status.textContent=config.configured?'On demand · only a minimal synthetic evidence packet is sent to OpenAI.':'Set the provider, model and API key on the server. The structured evidence overview works without an LLM.';if(response.draft)renderAssistant(response.draft,draftHost)}).catch(error=>{if(attached()){status.textContent=error.message;button.textContent='Explanation unavailable'}});
    button.onclick=async()=>{button.disabled=true;status.textContent='Preparing an evidence-based draft…';try{const result=await backendJSON('/case-explanation',{caseId:item.id,assessmentId:item.assessmentId,generate:true},55000);if(!attached())return;renderAssistant(result.draft,draftHost);button.textContent='Explanation saved';status.textContent='Draft saved for this assessment. Verify all statements before recording your decision.'}catch(error){if(attached()){status.textContent=error.message;button.disabled=false}}};
  }
  const original=renderCase;renderCase=function(){original();enhanceCase()};
  document.querySelector('[data-view="operations"]').addEventListener('click',loadOperations);
  switchView('operations');loadOperations();
})();
